arguments.file_text:
@using sv_ffd759425c254cd6bfdb186bc8a6a887.Services

<section class="settings-section">
    <h4>Profile</h4>
    <p class="text-muted">Manage your personal information</p>

    <div class="avatar-area">
        @if (!string.IsNullOrWhiteSpace(AvatarUrl))
        {
            <img src="@AvatarUrl" alt="Avatar" class="avatar-preview" />
        }
        else
        {
            <div class="avatar-placeholder">👤</div>
        }
        <span class="avatar-url text-muted">@AvatarUrl</span>
    </div>

    <div class="form-group mb-3">
        <label class="form-label" for="displayName">Display Name</label>
        <input id="displayName" type="text" class="form-control" @bind="DisplayName" />
    </div>

    <div class="form-group mb-3">
        <label class="form-label" for="email">Email</label>
        <input id="email" type="email" class="form-control" @bind="Email" />
    </div>

    <div class="form-group mb-3">
        <label class="form-label" for="bio">Bio</label>
        <textarea id="bio" class="form-control" rows="4" @bind="Bio"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible" role="alert">
            @statusMessage
            <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
        </div>
    }

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
            @if (isSaving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save Changes
        </button>
        <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@isSaving">
            Discard Changes
        </button>
    </div>
</section>

@code {
    [Parameter, EditorRequired]
    public UserProfile Profile { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName = "";
    private string Email = "";
    private string AvatarUrl = "";
    private string Bio = "";

    private string? statusMessage;
    private bool isError;
    private bool isSaving;

    protected override void OnParametersSet()
    {
        if (!isSaving)
        {
            LoadFromProfile();
        }
    }

    private void LoadFromProfile()
    {
        DisplayName = Profile.DisplayName;
        Email = Profile.Email;
        AvatarUrl = Profile.AvatarUrl;
        Bio = Profile.Bio;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
            await OnSave.InvokeAsync(updated);
            statusMessage = "Profile saved successfully!";
            isError = false;
        }
        catch
        {
            statusMessage = "Failed to save profile. Please try again.";
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }

    private void Discard()
    {
        LoadFromProfile();
        statusMessage = null;
    }
}

.settings-section {
    max-width: 640px;
}

.settings-section h4 {
    margin-bottom: 0.25rem;
}

.avatar-area {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: var(--bs-tertiary-bg, #f8f9fa);
    border-radius: 0.5rem;
}

.avatar-preview {
    width: 72px;
    height: 72px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid var(--bs-border-color, #dee2e6);
}

.avatar-placeholder {
    width: 72px;
    height: 72px;
    border-radius: 50%;
    background: var(--bs-secondary-bg, #e9ecef);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
}

.avatar-url {
    font-size: 0.85rem;
    word-break: break-all;
}

.button-group {
    display: flex;
    gap: 0.5rem;
    margin-top: 1rem;
}

@using sv_ffd759425c254cd6bfdb186bc8a6a887.Services

<section class="settings-section">
    <h4>Notifications</h4>
    <p class="text-muted">Control how you receive notifications</p>

    <div class="toggle-group">
        <div class="toggle-row">
            <div>
                <strong>Email Notifications</strong>
                <div class="text-muted small">Receive notifications via email</div>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch"
                       checked="@emailNotifications"
                       @onchange="e => emailNotifications = (bool)(e.Value ?? false)" />
            </div>
        </div>

        <div class="toggle-row">
            <div>
                <strong>Push Notifications</strong>
                <div class="text-muted small">Receive push notifications in your browser</div>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch"
                       checked="@pushNotifications"
                       @onchange="e => pushNotifications = (bool)(e.Value ?? false)" />
            </div>
        </div>

        <div class="toggle-row">
            <div>
                <strong>Weekly Digest</strong>
                <div class="text-muted small">Get a weekly summary of activity</div>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch"
                       checked="@weeklyDigest"
                       @onchange="e => weeklyDigest = (bool)(e.Value ?? false)" />
            </div>
        </div>
    </div>

    <h6 class="mt-4 mb-3">Muted Channels</h6>
    <div class="channel-list">
        @foreach (var channel in allChannels)
        {
            var isMuted = mutedChannels.Contains(channel);
            <div class="form-check">
                <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                       checked="@isMuted"
                       @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
            </div>
        }
    </div>

    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="alert alert-success mt-3" role="alert">@statusMessage</div>
    }

    <button class="btn btn-primary mt-3" @onclick="SaveAsync" disabled="@isSaving">
        @if (isSaving)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Save Preferences
    </button>
</section>

@code {
    [Parameter, EditorRequired]
    public NotificationPrefs Prefs { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<NotificationPrefs> OnSave { get; set; }

    [Parameter]
    public List<string> AllChannels { get; set; } = ["general", "announcements", "engineering", "design", "marketing", "support"];

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private List<string> allChannels = new();

    private string? statusMessage;
    private bool isSaving;

    protected override void OnParametersSet()
    {
        if (!isSaving)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(Prefs.MutedChannels);
            allChannels = AllChannels;
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
            await OnSave.InvokeAsync(updated);
            statusMessage = "Notification preferences saved!";
        }
        finally
        {
            isSaving = false;
        }
    }
}

