arguments.file_text:
.settings-section {
    max-width: 720px;
}

.settings-section h4 {
    margin-bottom: 0.25rem;
}

.tfa-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.85rem 0;
    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
}

@using sv_ffd759425c254cd6bfdb186bc8a6a887.Services

<section class="settings-section">
    <h4>Appearance</h4>
    <p class="text-muted">Customize how the app looks and feels</p>

    <div class="mb-4">
        <label class="form-label fw-semibold">Theme</label>
        <div class="d-flex gap-3">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="theme"
                           id="@($"theme-{theme}")" value="@theme"
                           checked="@(selectedTheme == theme)"
                           @onchange="() => selectedTheme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>
    </div>

    <div class="mb-4">
        <label class="form-label fw-semibold">Font Size</label>
        <div class="d-flex gap-3">
