            <div>
                <strong>Compact Mode</strong>
                <div class="text-muted small">Reduce spacing and padding</div>
            </div>
            <div class="form-check form-switch mb-0">
                <input class="form-check-input" type="checkbox" role="switch"
                       checked="@compactMode"
                       @onchange="e => compactMode = (bool)(e.Value ?? false)" />
            </div>
        </div>
    </div>

    <div class="preview-card mb-3">
        <h6 class="preview-title">Live Preview</h6>
        <div class="preview-area @GetPreviewClasses()">
            <div class="preview-header">Sample Header</div>
            <p class="preview-text">
                This is how your content will look with the selected appearance settings.
            </p>
            <div class="preview-actions">
                <span class="badge bg-primary">Tag</span>
                <span class="badge bg-secondary">Another Tag</span>
            </div>
        </div>
    </div>

    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="alert alert-success" role="alert">@statusMessage</div>
    }

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
        @if (isSaving)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Save
    </button>
</section>

@code {
    [Parameter, EditorRequired]
    public AppearanceSettings Appearance { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "en";
    private bool compactMode;

    private string? statusMessage;
    private bool isSaving;

    protected override void OnParametersSet()
    {
        if (!isSaving)
        {
            selectedTheme = Appearance.Theme;
            selectedFontSize = Appearance.FontSize;
            selectedLanguage = Appearance.Language;
            compactMode = Appearance.CompactMode;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(selectedTheme.ToLowerInvariant() switch
        {
            "dark" => "preview-dark",
            "system" => "preview-system",
            _ => "preview-light"
        });
        classes.Add(selectedFontSize.ToLowerInvariant() switch
        {
            "small" => "preview-font-sm",
            "large" => "preview-font-lg",
            _ => "preview-font-md"
        });
        if (compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
            await OnSave.InvokeAsync(updated);
            statusMessage = "Appearance settings saved!";
        }
        finally
        {
            isSaving = false;
        }
    }
}

