@page "/settings"
@using sv_ffd759425c254cd6bfdb186bc8a6a887.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="s => activeSection = s" />

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="d-flex justify-content-center py-5">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else if (loadError is not null)
        {
            <div class="alert alert-danger" role="alert">
                <strong>Error loading settings:</strong> @loadError
                <button class="btn btn-outline-danger btn-sm ms-3" @onclick="LoadDataAsync">Retry</button>
            </div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection Profile="profile!" OnSave="SaveProfileAsync" />
                    break;
                case "Notifications":
                    <NotificationsSection Prefs="notificationPrefs!" OnSave="SaveNotificationsAsync" />
                    break;
                case "Security":
                    <SecuritySection
                        Security="securitySettings!"
                        OnChangePassword="HandleChangePasswordAsync"
                        OnRevokeSession="HandleRevokeSessionAsync" />
                    break;
                case "Appearance":
                    <AppearanceSection Appearance="appearanceSettings!" OnSave="SaveAppearanceAsync" />
                    break;
            }
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;
    private string? loadError;

    private UserProfile? profile;
    private NotificationPrefs? notificationPrefs;
    private SecuritySettings? securitySettings;
    private AppearanceSettings? appearanceSettings;

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        isLoading = true;
        loadError = null;
        try
        {
            var profileTask = SettingsService.GetProfileAsync();
            var notifTask = SettingsService.GetNotificationPrefsAsync();
            var securityTask = SettingsService.GetSecuritySettingsAsync();
            var appearanceTask = SettingsService.GetAppearanceAsync();

            await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

            profile = profileTask.Result;
            notificationPrefs = notifTask.Result;
            securitySettings = securityTask.Result;
            appearanceSettings = appearanceTask.Result;
        }
        catch (Exception ex)
        {
            loadError = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task SaveProfileAsync(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notificationPrefs = updated;
    }

    private async Task HandleChangePasswordAsync((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task HandleRevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings updated)
    {
        await SettingsService.SaveAppearanceAsync(updated);
        appearanceSettings = updated;
    }
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 3.5rem);
    background: var(--bs-body-bg, #fff);
}

.settings-content {
    flex: 1;
    padding: 2rem 2.5rem;
    overflow-y: auto;
}

